import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_ORDINAL = r"(?:st|nd|rd|th)?"


def _month_number(name: str):
    return _MONTHS.get(name.lower().rstrip("."))


def _make(year: int, month: int, day: int):
    try:
        return date(year, month, day).isoformat()
    except (ValueError, OverflowError):
        return None


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = " ".join(s.strip().split())
    if not t:
        return "INVALID"

    result = None

    # YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (separator must be consistent)
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        result = _make(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Compact YYYYMMDD
    if result is None:
        m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
        if m:
            result = _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Ambiguous numeric DD/MM/YYYY (day-first convention), separator must be consistent
    if result is None:
        m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
        if m:
            result = _make(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    # D Month YYYY, e.g. "5 March 2024", "5th-Mar-2024"
    if result is None:
        m = re.fullmatch(
            r"(\d{1,2})" + _ORDINAL + r"[ \-/.]*([A-Za-z]+)\.?,?[ \-/.]*(\d{4})",
            t,
        )
        if m:
            month = _month_number(m.group(2))
            if month:
                result = _make(int(m.group(3)), month, int(m.group(1)))

    # Month D, YYYY, e.g. "March 5, 2024", "Mar 5 2024"
    if result is None:
        m = re.fullmatch(
            r"([A-Za-z]+)\.?[ \-/.]*(\d{1,2})" + _ORDINAL + r",?[ \-/.]*(\d{4})",
            t,
        )
        if m:
            month = _month_number(m.group(1))
            if month:
                result = _make(int(m.group(3)), month, int(m.group(2)))

    # YYYY Month D, e.g. "2024 March 5"
    if result is None:
        m = re.fullmatch(
            r"(\d{4})[ \-/.]*([A-Za-z]+)\.?[ \-/.]*(\d{1,2})" + _ORDINAL,
            t,
        )
        if m:
            month = _month_number(m.group(2))
            if month:
                result = _make(int(m.group(1)), month, int(m.group(3)))

    return result if result is not None else "INVALID"

import re
from datetime import date

_FULL_NAMES = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
_MONTHS = {}
for _i, _name in enumerate(_FULL_NAMES, start=1):
    _MONTHS[_name] = _i
    _MONTHS[_name[:3]] = _i
_MONTHS["sept"] = 9

_WEEKDAY = r"(?:(?:mon|tue|wed|thu|fri|sat|sun)[a-z]*\.?,?\s+)?"
_ORD = r"(?:st|nd|rd|th)?"

_ISO_RE = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")
_COMPACT_RE = re.compile(r"(\d{4})(\d{2})(\d{2})")
_NUMERIC_RE = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})")
# Groups: 1=month name, 2=day, 3=year
_MDY_TEXT_RE = re.compile(
    r"(?i)" + _WEEKDAY + r"([a-z]+)\.?\s+(\d{1,2})" + _ORD + r",?\s+(\d{4})"
)
# Groups: 1=day, 2=month name, 3=year
_DMY_TEXT_RE = re.compile(
    r"(?i)" + _WEEKDAY + r"(\d{1,2})" + _ORD + r"\s+([a-z]+)\.?,?\s+(\d{4})"
)


def _make(year: int, month: int, day: int):
    try:
        return date(year, month, day).isoformat()
    except (ValueError, OverflowError):
        return None


def _resolve_numeric(a: int, b: int, year: int):
    """Resolve two numeric parts. Prefer month-first unless only day-first is valid."""
    if a > 12 and b <= 12:      # must be DD/MM
        return _make(year, b, a)
    if b > 12 and a <= 12:      # must be MM/DD
        return _make(year, a, b)
    # Ambiguous or both invalid: try month-first, then day-first.
    return _make(year, a, b) or _make(year, b, a)


def _from_text(month_name: str, day: str, year: str):
    month = _MONTHS.get(month_name.lower())
    if month is None:
        return None
    return _make(int(year), month, int(day))


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"
    s = s.strip()
    if not s:
        return "INVALID"

    m = _ISO_RE.fullmatch(s)
    if m:
        result = _make(int(m.group(1)), int(m.group(3)), int(m.group(4)))
        return result or "INVALID"

    m = _COMPACT_RE.fullmatch(s)
    if m:
        result = _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        return result or "INVALID"

    m = _NUMERIC_RE.fullmatch(s)
    if m:
        result = _resolve_numeric(int(m.group(1)), int(m.group(3)), int(m.group(4)))
        return result or "INVALID"

    m = _MDY_TEXT_RE.fullmatch(s)
    if m:
        return _from_text(m.group(1), m.group(2), m.group(3)) or "INVALID"

    m = _DMY_TEXT_RE.fullmatch(s)
    if m:
        return _from_text(m.group(2), m.group(1), m.group(3)) or "INVALID"

    return "INVALID"

import re
from datetime import date

INVALID = "INVALID"

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}


def _normalize(s: str) -> str:
    t = s.strip().lower()
    # Drop a leading weekday name, e.g. "Monday, Nov 31 2022"
    t = re.sub(r"^(?:mon|tue|wed|thu|fri|sat|sun)[a-z]*\.?,?\s+", "", t)
    # Drop ordinal suffixes: 31st -> 31
    t = re.sub(r"(\d)(?:st|nd|rd|th)\b", r"\1", t)
    # Drop filler "of" and commas: "31st of November, 2022"
    t = re.sub(r"\bof\b", " ", t)
    t = t.replace(",", " ")
    return re.sub(r"\s+", " ", t).strip()


def _year(text: str) -> int:
    y = int(text)
    if len(text) == 2:
        # Two-digit years: 00-68 -> 2000s, 69-99 -> 1900s
        y += 2000 if y <= 68 else 1900
    return y


def _month(name: str):
    return _MONTHS.get(name)


def _build(y: int, m, d: int) -> str:
    if m is None:
        return INVALID
    try:
        return date(y, m, d).isoformat()
    except ValueError:
        return INVALID


def parse(s: str) -> str:
    if not isinstance(s, str):
        return INVALID

    t = _normalize(s)
    if not t:
        return INVALID

    # YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (consistent separator)
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        return _build(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Compact YYYYMMDD
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        return _build(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Numeric day-first: DD/MM/YYYY, DD-MM-YY, DD.MM.YYYY (consistent separator)
    m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4}|\d{2})", t)
    if m:
        return _build(_year(m.group(4)), int(m.group(3)), int(m.group(1)))

    # Day Month Year: "31 nov 2022", "31-nov-2022"
    m = re.fullmatch(r"(\d{1,2})[\s\-/.]*([a-z]+)[\s\-/.]*(\d{4}|\d{2})", t)
    if m:
        return _build(_year(m.group(3)), _month(m.group(2)), int(m.group(1)))

    # Month Day Year: "nov 31 2022", "nov-31-2022"
    m = re.fullmatch(r"([a-z]+)[\s\-/.]+(\d{1,2})[\s\-/.]+(\d{4}|\d{2})", t)
    if m:
        return _build(_year(m.group(3)), _month(m.group(1)), int(m.group(2)))

    # Year Month Day: "2022 nov 31", "2022-nov-31"
    m = re.fullmatch(r"(\d{4})[\s\-/.]+([a-z]+)[\s\-/.]+(\d{1,2})", t)
    if m:
        return _build(int(m.group(1)), _month(m.group(2)), int(m.group(3)))

    return INVALID

import re
from datetime import date

# Standard library only.

_MONTH_NAMES = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}

# Matches full or abbreviated English month names, with optional trailing period.
_MONTH = (
    r"(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?"
    r"|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\.?"
)
_ORDINAL = r"(?:st|nd|rd|th)?"
_WEEKDAY_PREFIX = re.compile(
    r"^(?:mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)[a-z]*\.?,?\s+", re.I
)

_ISO = re.compile(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})")
_DAY_FIRST_TEXT = re.compile(
    r"(\d{1,2})" + _ORDINAL + r"[\s\-/.]*" + _MONTH + r"[\s\-/.,]*(\d{4})", re.I
)
_MONTH_FIRST_TEXT = re.compile(
    _MONTH + r"[\s\-/.]*(\d{1,2})" + _ORDINAL + r"[\s\-/.,]*(\d{4})", re.I
)
_NUMERIC = re.compile(r"(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})")


def _normalize(s: str) -> str:
    s = s.strip()
    s = re.sub(r"\s+", " ", s)
    s = _WEEKDAY_PREFIX.sub("", s)
    return s.strip()


def _month_number(token: str) -> int:
    return _MONTH_NAMES[token.lower().rstrip(".")[:3]]


def _to_iso(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = _normalize(s)
    if not text:
        return "INVALID"

    m = _ISO.fullmatch(text)
    if m:
        y, mo, d = (int(g) for g in m.groups())
        return _to_iso(y, mo, d)

    m = _DAY_FIRST_TEXT.fullmatch(text)
    if m:
        d, mon, y = m.group(1), m.group(2), m.group(3)
        return _to_iso(int(y), _month_number(mon), int(d))

    m = _MONTH_FIRST_TEXT.fullmatch(text)
    if m:
        mon, d, y = m.group(1), m.group(2), m.group(3)
        return _to_iso(int(y), _month_number(mon), int(d))

    m = _NUMERIC.fullmatch(text)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if a > 12 and b <= 12:
            day, month = a, b          # unambiguous: day-first
        elif b > 12 and a <= 12:
            month, day = a, b          # unambiguous: month-first
        else:
            month, day = a, b          # ambiguous: default to MM/DD/YYYY
        return _to_iso(y, month, day)

    return "INVALID"

import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1, "feb": 2, "february": 2, "mar": 3, "march": 3,
    "apr": 4, "april": 4, "may": 5, "jun": 6, "june": 6, "jul": 7, "july": 7,
    "aug": 8, "august": 8, "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10, "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAYS = {
    "mon", "monday", "tue", "tues", "tuesday", "wed", "wednesday",
    "thu", "thur", "thurs", "thursday", "fri", "friday",
    "sat", "saturday", "sun", "sunday",
}

# Optional leading weekday: "Tuesday, ", "Tue. ", "Tue "
_LEADING_WORD = re.compile(r"([A-Za-z]+)\.?,?\s+(.+)")

# YYYY<sep>M[M]<sep>D[D]  (sep is -, / or ., and must be consistent)
_YMD = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")
# NN<sep>NN<sep>YYYY  (order inferred; see parse())
_NUM_DMY = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})")
# YYYYMMDD
_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})")
# Month D, YYYY  /  Mon. D YYYY
_MON_D_Y = re.compile(r"([A-Za-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})")
# D Month YYYY
_D_MON_Y = re.compile(r"(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\.?,?\s+(\d{4})")


def _make(year: int, month: int, day: int):
    """Return ISO date string if (year, month, day) is a real calendar date, else None."""
    try:
        return date(year, month, day).isoformat()
    except (ValueError, OverflowError):
        return None


def _month_num(name: str):
    return _MONTHS.get(name.lower().rstrip("."))


def _strip_weekday(t: str) -> str:
    """Remove a leading weekday name (full or abbreviated) if present."""
    m = _LEADING_WORD.fullmatch(t)
    if m and m.group(1).lower() in _WEEKDAYS:
        return m.group(2)
    return t


def _resolve_numeric(a: int, b: int, year: int):
    """
    Resolve NN<sep>NN<sep>YYYY.
    - If the second field is > 12, it can only be a day: MM/DD/YYYY.
    - Otherwise treat as DD/MM/YYYY (covers first field > 12 and ambiguous cases).
    Impossible combinations fail calendar validation in _make.
    """
    if b > 12:
        month, day = a, b
    else:
        month, day = b, a
    return _make(year, month, day)


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = " ".join(s.strip().split())
    if not t:
        return "INVALID"

    t = _strip_weekday(t)
    if not t:
        return "INVALID"

    m = _YMD.fullmatch(t)
    if m:
        result = _make(int(m.group(1)), int(m.group(3)), int(m.group(4)))
        return result or "INVALID"

    m = _COMPACT.fullmatch(t)
    if m:
        result = _make(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        return result or "INVALID"

    m = _NUM_DMY.fullmatch(t)
    if m:
        result = _resolve_numeric(int(m.group(1)), int(m.group(3)), int(m.group(4)))
        return result or "INVALID"

    m = _MON_D_Y.fullmatch(t)
    if m:
        month = _month_num(m.group(1))
        if month is None:
            return "INVALID"
        result = _make(int(m.group(3)), month, int(m.group(2)))
        return result or "INVALID"

    m = _D_MON_Y.fullmatch(t)
    if m:
        month = _month_num(m.group(2))
        if month is None:
            return "INVALID"
        result = _make(int(m.group(3)), month, int(m.group(1)))
        return result or "INVALID"

    return "INVALID"
